<?php
namespace App\Services\Marketing;
use Illuminate\Support\Facades\{DB,Crypt};
/** Internal adapter boundary only. Call after authenticating the provider callback and resolving its original delivery ID. */
final class MarketingEmailFeedback {
 public function recordVerified(string $merchant,string $delivery,string $provider,string $event,string $kind):bool {
  abort_unless($merchant===app(\App\Services\Marketing\Audience\AudienceDirectory::class)->merchant(),404);abort_unless(in_array($kind,['delivered','soft_bounce','hard_bounce','complaint'],true)&&preg_match('/^[a-z0-9_-]{1,40}$/D',$provider)&&strlen($event)>0&&strlen($event)<=255,422);
  return DB::transaction(function()use($merchant,$delivery,$provider,$event,$kind){$opt=app(MarketingEmailUnsubscribe::class);$opt->lock($merchant);$r=DB::table('marketing_email_deliveries')->where('merchant_key',$merchant)->where('id',$delivery)->lockForUpdate()->first();abort_unless($r,404);abort_unless(in_array($r->state,['sending','accepted','unknown','delivered','delayed','bounced','complained'],true),409,'No submitted email is available for this receipt.');$hash=hash('sha256',$merchant.'|'.$provider.'|'.$event);if(DB::table('marketing_email_feedback')->where('event_hash',$hash)->exists())return false;DB::table('marketing_email_feedback')->insert(['merchant_key'=>$merchant,'delivery_id'=>$delivery,'event_hash'=>$hash,'kind'=>$kind,'occurred_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$state=match($kind){'delivered'=>'delivered','complaint'=>'complained','soft_bounce'=>'delayed',default=>'bounced'};if(!in_array($r->state,['blocked','complained'],true)&&!($r->state==='bounced'&&($kind==='delivered'||($r->error_code==='hard_bounce'&&$kind==='soft_bounce'))))DB::table('marketing_email_deliveries')->where('id',$delivery)->update(['state'=>$state,'error_code'=>$kind==='delivered'?null:$kind,'updated_at'=>now()]);if(in_array($kind,['hard_bounce','complaint'],true)){$email=mb_strtolower(trim(Crypt::decryptString($r->recipient)));app(\App\Services\Marketing\Audience\AudienceDirectory::class)->subscribe('email',$email,'suppressed','verified_email_feedback:'.$provider,now());DB::table('marketing_email_deliveries')->where('merchant_key',$merchant)->where('recipient_hash',$r->recipient_hash)->where('state','queued')->update(['state'=>'blocked','error_code'=>$kind,'updated_at'=>now()]);}return true;});
 }
}
